import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Transplant the original PC activation/effect instructions into accepted-only replay methods. */
public final class ShockAcceptedMethods {
 static final String P="local/lito381/server/",PC=P+"ClientSession",H=P+"NativeAcceptedShockMutation",SP=P+"BattleSpellCatalog$ShockStunSpell",REQ=P+"Protocol$AttackSpellRequest",SCOPE=P+"NativeShockPlayerAction$Scope";
 static ClassNode read(JarFile j,String n)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(n+".class"))).accept(c,ClassReader.SKIP_DEBUG|ClassReader.EXPAND_FRAMES);return c;}
 static AbstractInsnNode prev(AbstractInsnNode n){do{n=n.getPrevious();}while(n!=null&&n.getOpcode()<0);return n;}
 static AbstractInsnNode next(AbstractInsnNode n){do{n=n.getNext();}while(n!=null&&n.getOpcode()<0);return n;}
 static List<AbstractInsnNode> range(AbstractInsnNode a,AbstractInsnNode end){var list=new ArrayList<AbstractInsnNode>();for(var n=a;n!=end;n=n.getNext()){if(n==null)throw new AssertionError("bounded slice");list.add(n);}return list;}
 static MethodInsnNode call(MethodNode m,String owner,String name){return Arrays.stream(m.instructions.toArray()).filter(n->n instanceof MethodInsnNode c&&c.owner.equals(owner)&&c.name.equals(name)).map(n->(MethodInsnNode)n).findFirst().orElseThrow();}
 static LabelNode labelBefore(AbstractInsnNode n){while(!(n instanceof LabelNode))n=n.getPrevious();return(LabelNode)n;}
 static record Parts(AbstractInsnNode roll,AbstractInsnNode effect,LabelNode effectLabel,LabelNode end,List<AbstractInsnNode> replay,int applied,int effectSlot,int now){}
 static Parts parts(MethodNode m,boolean world){int applied=world?54:50,now=world?34:27;var roll=call(m,SP,"rollStunSeconds");var rollStart=prev(prev(roll));var rollEnd=next(roll).getNext();var activate=call(m,P+"BattleTimedStatus","activateShockStun");var activationStart=(AbstractInsnNode)activate;for(int i=0;i<6;i++)activationStart=prev(activationStart);var post=next(activate);var activationEnd=world?post.getNext():null;var tail=world?((JumpInsnNode)next(post)).label:activationStart;while(!(tail instanceof VarInsnNode v&&v.getOpcode()==ISTORE&&v.var==applied))tail=tail.getNext();var place=call(m,P+"GameHub",world?"placeClassicWorldShockStunEffect":"placeShockStunEffect");var store=(AbstractInsnNode)place;while(!(store instanceof VarInsnNode st&&st.getOpcode()==LSTORE&&prev(store).getOpcode()==LCONST_0))store=store.getPrevious();var effect=prev(store);var test=next(next(store));if(!(test instanceof JumpInsnNode jump)||jump.getOpcode()!=IFEQ)throw new AssertionError("original applied effect gate");var list=new ArrayList<AbstractInsnNode>();list.addAll(range(rollStart,rollEnd));if(world){list.addAll(range(activationStart,activationEnd));var common=((JumpInsnNode)next(post)).label;list.addAll(range(common,tail.getNext()));}else list.addAll(range(activationStart,tail.getNext()));list.addAll(range(effect,jump.label));return new Parts(rollStart,effect,labelBefore(effect),jump.label,list,applied,((VarInsnNode)store).var,now);}
 static java.net.URLClassLoader hierarchy;
 static byte[] bytes(ClassNode c,boolean frames){var w=new ClassWriter(frames?ClassWriter.COMPUTE_FRAMES:ClassWriter.COMPUTE_MAXS){protected String getCommonSuperClass(String a,String b){try{Class<?> x=Class.forName(a.replace('/','.'),false,hierarchy),y=Class.forName(b.replace('/','.'),false,hierarchy);if(x.isAssignableFrom(y))return a;if(y.isAssignableFrom(x))return b;if(x.isInterface()||y.isInterface())return "java/lang/Object";do{x=x.getSuperclass();}while(!x.isAssignableFrom(y));return x.getName().replace('.','/');}catch(Exception e){throw new IllegalStateException(e);}}};c.accept(w);return w.toByteArray();}
 static String replayDesc(boolean world){return "(L"+SP+";L"+REQ+";L"+PC+";"+(world?"IIII":"IILjava/util/List;")+")J";}
 static MethodNode replay(ClassNode c,MethodNode original,boolean world,Parts p){var m=new MethodNode(0,"nativeAcceptedShock"+(world?"World":"Battle"),replayDesc(world),null,new String[]{"java/io/IOException"});var vars=new TreeMap<Integer,Integer>();if(world){int[] old={0,2,3,11,6,7,18,19};for(int i=0;i<old.length;i++)vars.put(old[i],i);}else{int[]old={0,2,3,5,11,12,46};for(int i=0;i<old.length;i++)vars.put(old[i],i);}int slot=world?8:7;var sizes=new TreeMap<Integer,Integer>();for(var n:p.replay)if(n instanceof VarInsnNode v)sizes.merge(v.var,v.getOpcode()==LLOAD||v.getOpcode()==LSTORE||v.getOpcode()==DLOAD||v.getOpcode()==DSTORE?2:1,Math::max);sizes.put(p.now,2);if(world)sizes.put(p.applied,1);for(var e:sizes.entrySet())if(!vars.containsKey(e.getKey())){vars.put(e.getKey(),slot);slot+=e.getValue();}
  m.instructions.add(new MethodInsnNode(INVOKESTATIC,"java/lang/System","nanoTime","()J",false));m.instructions.add(new VarInsnNode(LSTORE,vars.get(p.now)));if(world){m.instructions.add(new InsnNode(ICONST_0));m.instructions.add(new VarInsnNode(ISTORE,vars.get(p.applied)));}var labels=new IdentityHashMap<LabelNode,LabelNode>();for(var n:original.instructions)if(n instanceof LabelNode l)labels.put(l,new LabelNode());for(var n:p.replay){if(n==p.effect)m.instructions.add(labels.get(p.effectLabel));if(n instanceof FrameNode)continue;var copy=n.clone(labels);if(copy instanceof VarInsnNode v)v.var=vars.get(v.var);if(copy instanceof IincInsnNode)throw new AssertionError("no arithmetic rewritten in effect replay");m.instructions.add(copy);}m.instructions.add(labels.get(p.end));m.instructions.add(new VarInsnNode(LLOAD,vars.get(p.effectSlot)));m.instructions.add(new InsnNode(LRETURN));return m;}
 static void patch(ClassNode c){if(c.name.equals(SCOPE)){c.fields.add(new FieldNode(0,"nativeAcceptedShockPlan","Ljava/lang/Object;",null,null));return;}if(c.name.equals(P+"NativeAreaMaterialAction")){var old=c.methods.stream().filter(m->m.name.equals("captureOutput")).findFirst().orElseThrow();old.name="nativeAcceptedShockOriginalCaptureOutput";var m=new MethodNode(old.access,"captureOutput",old.desc,null,old.exceptions.toArray(String[]::new));for(int i=0;i<3;i++)m.instructions.add(new VarInsnNode(ALOAD,i));m.instructions.add(new MethodInsnNode(INVOKESTATIC,H,"captureOutput",old.desc,false));m.instructions.add(new InsnNode(IRETURN));c.methods.add(m);return;}if(c.name.equals(P+"NativeAcceptedHpCompletion")){int n=0;for(var m:c.methods)if(m.name.equals("run"))for(var node:m.instructions)if(node instanceof MethodInsnNode call&&call.owner.equals(P+"NativeShockPlayerAction")&&call.name.equals("completed")){call.owner=H;n++;}if(n!=1)throw new AssertionError("one existing completion handoff");return;}
  for(boolean world:new boolean[]{false,true}){var m=c.methods.stream().filter(q->q.name.equals("nativeShockPlayer"+(world?"World":"Battle")+"Body")).findFirst().orElseThrow();var p=parts(m,world);c.methods.add(replay(c,m,world,p));var guard=new InsnList();guard.add(new VarInsnNode(ALOAD,0));guard.add(new VarInsnNode(ALOAD,2));guard.add(new VarInsnNode(ALOAD,3));guard.add(new VarInsnNode(ALOAD,world?11:5));guard.add(world?new InsnNode(ACONST_NULL):new VarInsnNode(ALOAD,46));guard.add(new MethodInsnNode(INVOKESTATIC,H,"plan","(L"+PC+";L"+SP+";L"+REQ+";L"+PC+";Ljava/util/List;)Z",false));guard.add(new JumpInsnNode(IFNE,p.effectLabel));m.instructions.insertBefore(p.roll,guard);}
  var recomputed=new ClassNode();new ClassReader(bytes(c,true)).accept(recomputed,ClassReader.EXPAND_FRAMES);for(int i=0;i<c.methods.size();i++){var old=c.methods.get(i);if(old.name.startsWith("nativeAcceptedShock")||old.name.startsWith("nativeShockPlayer")&&old.name.endsWith("Body"))c.methods.set(i,recomputed.methods.stream().filter(m->m.name.equals(old.name)&&m.desc.equals(old.desc)).findFirst().orElseThrow());}
 }
 public static void main(String[]a)throws Exception{var urls=new ArrayList<java.net.URL>();urls.add(Path.of(a[1]).toUri().toURL());try(var libs=Files.list(Path.of(System.getProperty("user.dir"),"lib"))){for(var p:libs.filter(p->p.toString().endsWith(".jar")).toList())urls.add(p.toUri().toURL());}hierarchy=new java.net.URLClassLoader(urls.toArray(java.net.URL[]::new),ClassLoader.getPlatformClassLoader());try(var j=new JarFile(a[1])){for(var name:List.of(PC,SCOPE,P+"NativeAreaMaterialAction",P+"NativeAcceptedHpCompletion")){var c=read(j,name);patch(c);byte[] b=bytes(c,false);if(a[0].equals("splice")){var p=Path.of(a[2]).resolve(name+".class");Files.createDirectories(p.getParent());Files.write(p,b);}else try(var z=new JarFile(a[2])){if(!Arrays.equals(b,bytes(read(z,name),false)))throw new AssertionError(name);}}}System.out.println("PASS bounded original PC87 mutation replay and existing HP completion handoff");}
}
